  'page.goodIdeasGrowThroughConversationI': { en: 'Good ideas grow through conversation. I help bring people together to learn, build, and share what actually works.', es: 'Las buenas ideas crecen al conversar. Ayudo a reunir personas para aprender, construir y compartir lo que funciona.' },
