  'page.handsOnSessionsAroundReactTypescript': { en: 'Hands-on sessions around React, TypeScript, testing, tooling, and workflow design for teams that want to level up together.', es: 'Sesiones prácticas de React, TypeScript, pruebas, herramientas y diseño de flujos para equipos que quieren mejorar juntos.' },
