  'page.iReplyOnWhatsappWithQuestions': { en: 'I reply on WhatsApp with questions or a time to talk. You can also book a call directly.', es: 'Respondo por WhatsApp con preguntas o un horario para conversar. También puedes reservar una llamada directamente.' },
  'page.itDependsOnTheGoalA': { en: 'It depends on the goal: a single talk, a workshop, a focused improvement project, or a longer engagement. We agree on scope and timing after the first conversation.', es: 'Depende del objetivo: una charla, un taller, una mejora concreta o una colaboración más larga. Acordamos el alcance y los plazos después de la primera conversación.' },
