  'page.termsAndConditionsForUsingSanti020k': { en: 'Terms and conditions for using santi020k.com, including acceptable use, intellectual property, external links, and limitations.', es: 'Términos y condiciones de uso de santi020k.com, incluidos el uso aceptable, la propiedad intelectual, los enlaces externos y las limitaciones.' },
  'page.testing': { en: 'Testing', es: 'Pruebas' },
  'page.testingAndAccessibilityChecks': { en: 'Testing and accessibility checks', es: 'Pruebas y controles de accesibilidad' },
  'page.testingLintingAndCiCdSystems': { en: 'Testing, linting, and CI/CD systems that teams actually keep because they improve confidence instead of slowing work down.', es: 'Sistemas de pruebas, linting y CI/CD que los equipos conservan porque aportan confianza sin frenar el trabajo.' },
  'page.thatCompounds': { en: 'that compounds', es: 'que se potencia con el tiempo' },
  'page.thatFitTheWorkflow': { en: 'that fit the workflow', es: 'adaptados al flujo de trabajo' },
  'page.thatMeansMeasuringOutcomesInsteadOf': { en: 'That means measuring outcomes instead of counting tools. Faster feedback matters when it reduces waiting. Automation matters when it removes repeated work. Standards matter when they help people make decisions without guessing what “good” means.', es: 'Esto implica medir resultados en lugar de contar herramientas. La retroalimentación rápida importa cuando reduce la espera. La automatización, cuando elimina trabajo repetido. Los estándares, cuando permiten decidir sin adivinar qué significa hacerlo bien.' },
  'page.theArchivedDesignsAndContentStay': { en: 'The archived designs and content stay frozen. Their software stays maintained. Forms and comments are disabled, and every archive has a way back to today’s website.', es: 'El diseño y el contenido de los archivos quedan congelados. Su software se mantiene actualizado. Los formularios y comentarios están desactivados, y cada archivo ofrece un regreso al sitio actual.' },
  'page.theBestAutomationRemovesToilRepetitive': { en: 'The best automation removes toil — repetitive, low-judgment work that slows teams down. It should never replace the thinking that makes products worth building.', es: 'La mejor automatización elimina el trabajo repetitivo que frena a los equipos. Nunca debe sustituir el criterio que hace que un producto merezca construirse.' },
  'page.theCountriesCitiesAndRegionsI': { en: 'The countries, cities, and regions I have visited, with room for more memories as I write.', es: 'Los países, ciudades y regiones que he visitado, con espacio para más recuerdos a medida que escribo.' },
  'page.theCurrentCanvas': { en: 'The current canvas', es: 'El lienzo actual' },
  'page.theDeveloperExperienceOfACodebase': { en: 'The developer experience of a codebase shapes how fast and confidently the team can move. Bad DX compounds. Good DX compounds too — invest early and measure it.', es: 'La experiencia de desarrollo determina la velocidad y confianza del equipo. Sus efectos, buenos y malos, se acumulan: invierte pronto y mídela.' },
  'page.theEvidence': { en: 'The evidence', es: 'La evidencia' },
  'page.theFinalV3110Site': { en: 'The final v3.11.0 site: a mature portfolio and blog built on Lumen, with a growing family of personal products.', es: 'El sitio final de v3.11.0: un portafolio y blog maduros construidos con Lumen y una familia creciente de productos personales.' },
  'page.theGoalIsToSolveThe': { en: 'The goal is to solve the problem, not to use the newest tool. Stable, well-understood solutions let the team focus on the actual product.', es: 'El objetivo es resolver el problema, no usar la herramienta más nueva. Las soluciones estables y conocidas permiten enfocarse en el producto.' },
  'page.theLargestCrossFunctionalTeamI': { en: 'The largest cross-functional team I’ve led.', es: 'El mayor equipo multidisciplinario que he liderado.' },
  'page.themePreferenceAndRecentSiteSearch': { en: 'Theme preference and recent site-search terms are stored in localStorage on your device. The service worker may also keep previously visited pages and assets in Cache Storage for offline access. Saved responses can retain their original URL, including search terms. Clearing this site’s browser data removes both.', es: 'Tu preferencia de tema y tus búsquedas recientes se guardan en el localStorage del dispositivo. El service worker también puede guardar páginas y recursos visitados en Cache Storage para usarlos sin conexión. Las respuestas guardadas pueden conservar su URL original, incluidos los términos de búsqueda. Borrar los datos del sitio en el navegador elimina ambos.' },
