  'page.thePlacesWhereHandsOnEngineering': { en: 'The places where hands-on engineering and technical leadership can make the biggest difference.', es: 'Los ámbitos donde la ingeniería práctica y el liderazgo técnico pueden aportar más.' },
  'page.thePortfolioHasTheProjectEvidence': { en: 'The portfolio has the project evidence; the blog has the thinking behind the decisions.', es: 'El portafolio reúne la evidencia de los proyectos; el blog, el razonamiento detrás de las decisiones.' },
  'page.thePortfolioShowsHowTheseIdeas': { en: 'The portfolio shows how these ideas become products, rules, editor feedback, documentation, and reusable component systems.', es: 'El portafolio muestra cómo estas ideas se convierten en productos, reglas, ayuda en el editor, documentación y sistemas de componentes reutilizables.' },
  'page.thePracticeBehindTheWriting': { en: 'The practice behind the writing.', es: 'La práctica detrás de los artículos.' },
  'page.thePrinciplesIComeBackTo': { en: 'The principles I come back to when a product is moving fast and the team needs decisions that hold.', es: 'Los principios a los que vuelvo cuando un producto avanza rápido y el equipo necesita decisiones sólidas.' },
  'page.thePrivacyPageExplainsBrowserStorage': { en: 'The Privacy page explains browser storage, hosting metrics, third-party services, and how information connected with the site is handled. It forms part of these terms where relevant.', es: 'La página de Privacidad explica el almacenamiento del navegador, las métricas del hosting, los servicios externos y el tratamiento de la información relacionada con el sitio. Forma parte de estos términos cuando corresponde.' },
  'page.theReleasedV400Design': { en: 'The released v4.0.0 design: warmer portraits, sculpted typography, and a personal studio for products, writing, and the stories behind the work.', es: 'El diseño publicado de v4.0.0: retratos más cálidos, tipografía esculpida y un estudio personal de productos, artículos e historias detrás del trabajo.' },
  'page.theRouteMayHaveChangedOr': { en: 'The route may have changed, or the page may never have existed in this version of the site.', es: 'La ruta pudo cambiar o quizá la página nunca existió en esta versión del sitio.' },
  'page.theseTermsMayBeUpdatedWhen': { en: 'These terms may be updated when the site or applicable requirements change. Updated terms take effect when published here. These terms are governed by the laws of the Republic of Colombia, without limiting any rights that applicable law gives you.', es: 'Estos términos pueden actualizarse cuando cambien el sitio o los requisitos aplicables. Los cambios entran en vigor al publicarse aquí. Se rigen por las leyes de la República de Colombia, sin limitar los derechos que te conceda la ley aplicable.' },
  'page.theShapeOfTheWork': { en: 'The shape of the work', es: 'La forma del trabajo' },
  'page.theSiteLinksToServicesAnd': { en: 'The site links to services and websites operated by others, including GitHub, LinkedIn, Medium, Buttondown, Giscus, and WhatsApp. Their content, availability, security, and privacy practices are controlled by their respective operators and governed by their own terms.', es: 'El sitio enlaza servicios y páginas operados por terceros, incluidos GitHub, LinkedIn, Medium, Buttondown, Giscus y WhatsApp. Sus operadores controlan el contenido, la disponibilidad, la seguridad y la privacidad, según sus propios términos.' },
