  'page.thisStatementDoesNotReplaceApplicable': { en: 'This statement does not replace applicable law. Use the email below to request alternative formats or further information about how issues are handled.', es: 'Esta declaración no sustituye la ley aplicable. Escribe al correo de abajo para pedir formatos alternativos o información sobre la gestión de incidencias.' },
  'page.threeWaysIntoMyWorkThe': { en: 'Three ways into my work: the tools, the decisions, and the reasons behind them.', es: 'Tres caminos para conocer mi trabajo: las herramientas, las decisiones y las razones que hay detrás.' },
